    cycle_html = '<div class="searchbar"><label for="cycle-search">搜索周期</label><input id="cycle-search" data-filter="cycles" placeholder="试试：LoRA、隐私、截断、未运行"><span class="result-count" data-count="cycles">57 / 57 项</span></div><noscript><p class="no-js">脚本关闭时全部周期仍可展开阅读，浏览器查找可检索正文。</p></noscript>'
